DO $$ DECLARE v_form_id uuid; BEGIN
 SELECT id INTO v_form_id FROM public.dynamic_forms WHERE slug='funnel-aguia-sul-sinalizacao';
 IF v_form_id IS NULL THEN INSERT INTO public.dynamic_forms (slug,name,description,status,config_json,whatsapp_config) VALUES ('funnel-aguia-sul-sinalizacao','Orçamento · Águia Sul Sinalização','Funil individual para pintura e sinalização horizontal','published','{"auto_advance_ms":250}'::jsonb,'{"enabled":true}'::jsonb) RETURNING id INTO v_form_id;
 ELSE UPDATE public.dynamic_forms SET status='published',name='Orçamento · Águia Sul Sinalização',description='Funil individual para pintura e sinalização horizontal' WHERE id=v_form_id; DELETE FROM public.dynamic_form_conditions WHERE form_id=v_form_id; DELETE FROM public.dynamic_form_questions WHERE form_id=v_form_id; END IF;
